'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PI = require( '@stdlib/constants/float64/pi' );


// MAIN //

/**
* Returns the variance for a half-normal distribution with scale parameter `sigma`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} variance
*
* @example
* var y = variance( 1.0 );
* // returns ~0.3633802276324186
*
* @example
* var y = variance( 4.0 );
* // returns ~5.814083642118698
*
* @example
* var y = variance( NaN );
* // returns NaN
*
* @example
* var y = variance( 0.0 );
* // returns NaN
*/
function variance( sigma ) {
	if (
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}
	return ( sigma * sigma ) * ( 1.0 - ( 2.0 / PI ) );
}


// EXPORTS //

module.exports = variance;
